CREATE TABLE IF NOT EXISTS "IntegrationConnection" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "providerId" text NOT NULL, status text NOT NULL CHECK(status IN ('CONNECTED','DISCONNECTED','ERROR')), "encryptedTokenCipher" text, scopes jsonb NOT NULL DEFAULT '[]'::jsonb, "consentVersion" text NOT NULL, "lastSyncAt" timestamptz, "createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("userId","providerId"));
CREATE TABLE IF NOT EXISTS "IntegrationWebhookEvent" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "providerId" text NOT NULL, "externalEventId" text NOT NULL UNIQUE, "signatureValid" boolean NOT NULL, "processedAt" timestamptz);
